+        let error = |message: String| {
+            clap::Error::raw(
+                clap::error::ErrorKind::ValueValidation,
+                format!("{message}\n"),
+            )
+            .with_cmd(cmd)
+        };
+        let value = value.to_str().ok_or_else(|| error("--args-json is not valid UTF-8".into()))?;
+        parse_runtime_args_json(value).map_err(error)
+    }
